     stamens: { n: null, fused: false, note: { en: 'many (about twenty to thirty), on the hypanthium', fr: 'nombreuses (une vingtaine à une trentaine), sur l’hypanthe' } }, carpels: { n: 1, fused: false, note: { en: 'one carpel, two ovules of which one aborts', fr: 'un carpelle, deux ovules dont un avorte' } },
